    lines: [{ qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 95000
  // first discount = 0
  // bulk discount = 95000 * 2.5 / 100 = 2375
  // lineAmount = 95000 - 2375 = 92625
  // vat = 92625 * 21 / 100 = 19451.25 -> 19451
  // total = 95000 - 2375 + 19451 = 112076
  assert.deepEqual(totals, {
