import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, invoiceTotals } from '../src/totals.js';

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
});

test('lineTotal with qty of 1', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 50 }), 50);
});

test('lineTotal with qty of 0', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 9500 }), 0);
});

test('lineTotal with large quantities', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 5000 }), 5000000);
});

test('invoiceTotals calculates subtotal and total for single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 47500,
    discount: 0,
    vat: 9975,
    voucher: 0,
    total: 57475,
  });
});

test('invoiceTotals calculates subtotal and total for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 215000,
    discount: 0,
    vat: 45150,
    voucher: 0,
    total: 260150,
  });
});

test('invoiceTotals with multiple lines of different products', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
      { qty: 100, unitPrice: 37, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 218700,
    discount: 0,
    vat: 45483,
    voucher: 0,
    total: 264183,
  });
});

test('invoiceTotals calculates discount for single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 9500, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 9500,
    vat: 17955,
    voucher: 0,
    total: 103455,
  });
});

test('invoiceTotals with 100% discount on one line', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 100, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 215000,
    discount: 120000,
    vat: 19950,
    voucher: 0,
    total: 114950,
  });
});

test('invoiceTotals with decimal discount percent', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 9500, discountPercent: 12.5, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 11875,
    vat: 17456,
    voucher: 0,
    total: 100581,
  });
});

test('invoiceTotals clamps negative amounts to 0', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100, discountPercent: 200, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with VAT 21%', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 9500, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 950000,
    discount: 0,
    vat: 199500,
    voucher: 0,
    total: 1149500,
  });
});

test('invoiceTotals with VAT 9%', () => {
  const invoice = {
    lines: [{ qty: 1000, unitPrice: 37, discountPercent: 0, vatRate: 9 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 37000,
    discount: 0,
    vat: 3330,
    voucher: 0,
    total: 40330,
  });
});

test('invoiceTotals with VAT 0%', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 60000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 60000,
    discount: 0,
    vat: 0,
    voucher: 0,
    total: 60000,
  });
});

test('invoiceTotals with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 100, unitPrice: 37, discountPercent: 0, vatRate: 9 },
      { qty: 1, unitPrice: 60000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // line 1 (qty 10): bulk discount 2375, vat 19451
  // line 2 (qty 100): bulk discount 92, vat 325
  // line 3 (qty 1): no bulk discount, vat 0
  assert.deepEqual(totals, {
    subtotal: 158700,
    discount: 2467,
    vat: 19776,
    voucher: 0,
    total: 176009,
  });
});

test('invoiceTotals VAT on discounted amount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 9500, discountPercent: 50, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // line discount: 47500, bulk discount: 1188, vat on remaining: 9726
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 48688,
    vat: 9726,
    voucher: 0,
    total: 56038,
  });
});

test('invoiceTotals with voucher', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 }],
    voucher: { code: 'SAVE10', amount: 10000 },
  };
  const totals = invoiceTotals(invoice);
  // bulk discount applied: 95000 * 2.5 / 100 = 2375
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 2375,
    vat: 19451,
    voucher: 10000,
    total: 102076,
  });
});

test('invoiceTotals voucher = 0 when no voucher applied', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals total formula: subtotal - discount + vat - voucher', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 9500, discountPercent: 5, vatRate: 21 }],
    voucher: { code: 'SAVE5', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - totals.voucher);
});

test('invoiceTotals with discount and voucher', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 10, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 20, vatRate: 21 },
    ],
    voucher: { code: 'SAVE', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  // line 1: 95000 - 9500 (line discount) - 2138 (bulk discount) = 83362 lineAmount, vat 17506
  // line 2: 120000 - 24000 (line discount) = 96000 lineAmount, vat 20160
  // total discount = 9500 + 2138 + 24000 = 35638
  assert.deepEqual(totals, {
    subtotal: 215000,
    discount: 35638,
    vat: 37666,
    voucher: 5000,
    total: 212028,
  });
});

test('invoiceTotals with empty lines array', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 0,
    discount: 0,
    vat: 0,
    voucher: 0,
    total: 0,
  });
});

test('invoiceTotals with bulk discount (qty >= 10)', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 95000
  // first discount = 0
  // bulk discount = 95000 * 2.5 / 100 = 2375
  // lineAmount = 95000 - 2375 = 92625
  // vat = 92625 * 21 / 100 = 19451.25 -> 19451
  // total = 95000 - 2375 + 19451 = 112076
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 2375,
    vat: 19451,
    voucher: 0,
    total: 112076,
  });
});

test('invoiceTotals without bulk discount (qty < 10)', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 9500, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 85500
  // first discount = 0
  // no bulk discount (qty < 10)
  // lineAmount = 85500
  // vat = 85500 * 21 / 100 = 17955
  // total = 85500 + 17955 = 103455
  assert.deepEqual(totals, {
    subtotal: 85500,
    discount: 0,
    vat: 17955,
    voucher: 0,
    total: 103455,
  });
});

test('invoiceTotals bulk discount applied after line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 9500, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 95000
  // first discount = 95000 * 10 / 100 = 9500
  // after first discount = 85500
  // bulk discount = 85500 * 2.5 / 100 = 2137.5 -> 2138
  // lineAmount = 85500 - 2138 = 83362
  // vat = 83362 * 21 / 100 = 17506.02 -> 17506
  // total discount = 9500 + 2138 = 11638
  // total = 95000 - 11638 + 17506 = 100868
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 11638,
    vat: 17506,
    voucher: 0,
    total: 100868,
  });
});

test('invoiceTotals bulk discount with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // line 1: subtotal = 95000, bulk discount = 2375, vat = 19451
  // line 2: subtotal = 47500, no bulk discount, vat = 9975
  // total discount = 2375
  // total = 142500 - 2375 + 29426 = 169551
  assert.deepEqual(totals, {
    subtotal: 142500,
    discount: 2375,
    vat: 29426,
    voucher: 0,
    total: 169551,
  });
});

test('invoiceTotals bulk discount with qty exactly 10', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 10000
  // bulk discount = 10000 * 2.5 / 100 = 250
  // vat = 0
  // total = 10000 - 250 = 9750
  assert.deepEqual(totals, {
    subtotal: 10000,
    discount: 250,
    vat: 0,
    voucher: 0,
    total: 9750,
  });
});

test('invoiceTotals no bulk discount with qty 9', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 9000
  // no bulk discount (qty < 10)
  // vat = 0
  // total = 9000
  assert.deepEqual(totals, {
    subtotal: 9000,
    discount: 0,
    vat: 0,
    voucher: 0,
    total: 9000,
  });
});

test('invoiceTotals bulk discount with high qty', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 9500, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 950000
  // bulk discount = 950000 * 2.5 / 100 = 23750
  // lineAmount = 926250
  // vat = 926250 * 21 / 100 = 194512.5 -> 194512
  // total = 950000 - 23750 + 194512 = 1120762
  assert.deepEqual(totals, {
    subtotal: 950000,
    discount: 23750,
    vat: 194512,
    voucher: 0,
    total: 1120762,
  });
});

test('invoiceTotals bulk discount with both line discount and bulk discount', () => {
  const invoice = {
    lines: [{ qty: 20, unitPrice: 10000, discountPercent: 5, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 200000
  // line discount = 200000 * 5 / 100 = 10000
  // after line discount = 190000
  // bulk discount = 190000 * 2.5 / 100 = 4750
