  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // DEV-HOUR (qty 10): bulk discount 2375, vat 19451
  // LOGO-PACK (qty 1): no bulk discount, vat 25200
  assert.deepEqual(totals, {
    subtotal: 215000,
    discount: 2375,
    vat: 44651,
    voucher: 0,
    total: 257276,
  });
});

