    customerId: 'C-001', // gold tier = 5%
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 }, // uses 5% from tier, plus bulk discount
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 }, // explicit 20%, no bulk
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // line 1: line discount 4750, bulk discount 2256, vat 18480
  // line 2: line discount 24000, no bulk, vat 20160
  // total discount = 4750 + 2256 + 24000 = 31006
  // total vat = 18480 + 20160 = 38640
  // total = 215000 - 31006 + 38640 = 222634
  assert.deepEqual(totals, {
    subtotal: 215000,
    discount: 31006,
    vat: 38640,
    voucher: 0,
    total: 222634,
  });
});

