test('invoiceTotals calculates discount for single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // line discount: 9500, bulk discount: 2138, vat: 17506
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 11638,
    vat: 17506,
    voucher: 0,
    total: 100868,
  });
});

test('invoiceTotals calculates discount for multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // line 1: line discount 9500, bulk discount 2138, vat 17506
  // line 2: line discount 24000, no bulk, vat 20160
  // total discount = 9500 + 2138 + 24000 = 35638
  // total vat = 17506 + 20160 = 37666
  // total = 215000 - 35638 + 37666 = 217028
  assert.deepEqual(totals, {
    subtotal: 215000,
    discount: 35638,
    vat: 37666,
    voucher: 0,
    total: 217028,
  });
});

