  const csv = exportCsv([issued.value]);
  assert(csv.includes('950.00')); // subtotal
  assert(csv.includes('194.51')); // vat with bulk discount
  assert(csv.includes('1120.76')); // invoice total with bulk discount
});

test('exportCsv includes customer name', () => {
